#include <TextEdit.h>
#include <Windows.h>
#include <Files.h>
#include <stdio.h>
#include <string.h>
static char output[16384];
static char *query(char *p,TEHandle h){short inputs[]={0,1,2,4,8,15},i,mode;TextStyle style;Boolean result;p+=sprintf(p,"[");for(i=0;i<6;i++){mode=inputs[i];memset(&style,0xa5,sizeof(style));result=TEContinuousStyle(&mode,&style,h);p+=sprintf(p,"%s{\"requested\":%d,\"mode\":%d,\"result_byte\":%u,\"attributes\":[",i?",":"",inputs[i],mode,result);if(mode&1)p+=sprintf(p,"%d",style.tsFont);else p+=sprintf(p,"null");if(mode&2)p+=sprintf(p,",%u",style.tsFace);else p+=sprintf(p,",null");if(mode&4)p+=sprintf(p,",%d",style.tsSize);else p+=sprintf(p,",null");if(mode&8)p+=sprintf(p,",%u,%u,%u",style.tsColor.red,style.tsColor.green,style.tsColor.blue);else p+=sprintf(p,",null,null,null");p+=sprintf(p,"]}");}return p+sprintf(p,"]");}
static char *height_ranges(char *p,TEHandle h){long ranges[][2]={{0,0},{32767,0},{32767,1},{0,32767},{32767,32767},{-1,-1},{1,-1},{-1,1},{2,1},{1,2}};short i;p+=sprintf(p,"[");for(i=0;i<10;i++)p+=sprintf(p,"%s[%ld,%ld,%ld]",i?",":"",ranges[i][0],ranges[i][1],TEGetHeight(ranges[i][0],ranges[i][1],h));return p+sprintf(p,"]");}
static void select_without_draw(TEHandle h,short start,short end){(*h)->selStart=start;(*h)->selEnd=end;}
int main(void){Rect r={30,20,200,300};TEHandle h;TextStyle s;char *p=output;short file;long n;OSErr e;InitGraf(&qd.thePort);InitFonts();InitWindows();TEInit();TextFont(4);TextFace(0);TextSize(9);h=TEStyleNew(&r,&r);p+=sprintf(p,"{\"schema\":1,\"probe\":\"te-continuous-v1\",\"textedit\":{\"initial\":");p=query(p,h);p+=sprintf(p,",\"height_empty\":");p=height_ranges(p,h);s.tsFont=3;s.tsFace=1;s.filler=0;s.tsSize=12;s.tsColor.red=s.tsColor.green=s.tsColor.blue=0;TESetStyle(15,&s,0,h);p+=sprintf(p,",\"pending\":");p=query(p,h);TESetText("abcd",4,h);select_without_draw(h,1,3);TESetStyle(7,&s,0,h);select_without_draw(h,0,4);p+=sprintf(p,",\"mixed\":");p=query(p,h);p+=sprintf(p,",\"height_mixed\":");p=height_ranges(p,h);s.tsFont=0;s.tsFace=1;s.tsSize=12;TESetStyle(15,&s,0,h);select_without_draw(h,1,3);s.tsFace=3;TESetStyle(2,&s,0,h);select_without_draw(h,0,4);p+=sprintf(p,",\"shared_face\":");p=query(p,h);select_without_draw(h,1,1);p+=sprintf(p,",\"boundary_caret\":");p=query(p,h);select_without_draw(h,1,3);s.tsFace=2;TESetStyle(2,&s,0,h);select_without_draw(h,0,4);p+=sprintf(p,",\"no_common_face\":");p=query(p,h);s.tsFace=0;TESetStyle(2,&s,0,h);p+=sprintf(p,",\"plain\":");p=query(p,h);TESetText("A\r",2,h);p+=sprintf(p,",\"height_cr\":");p=height_ranges(p,h);TESetText("A\rB",3,h);p+=sprintf(p,",\"height_two\":");p=height_ranges(p,h);TEDispose(h);p+=sprintf(p,"}}\n");e=Create("\pTEContinuousProbe.json",0,'ttxt','TEXT');if(e&&e!=dupFNErr)return 2;if(FSOpen("\pTEContinuousProbe.json",0,&file))return 3;SetEOF(file,0);n=p-output;e=FSWrite(file,&n,output);FSClose(file);FlushVol(0,0);return e?4:0;}
